import {skills} from './model.mjs';
import {learningExercises} from './journey.mjs';

export function entryHeader(c){const {state,t,brandMark,icon}=c;return `<header class="entry-header"><button class="brand entry-brand" data-action="intro-home" aria-label="RePath AI">${brandMark()}<span>RePath</span><span class="brand-ai">AI</span></button><span class="entry-brand-purpose">${t('brandPurpose')}</span><nav class="entry-nav"><button data-action="pricing">${t('seePlans')}</button><label class="language-control">${icon('globe')}<select id="language" aria-label="Language / 语言 / Bahasa"><option value="zh" ${state.lang==='zh'?'selected':''}>简体中文</option><option value="en" ${state.lang==='en'?'selected':''}>English</option><option value="ms" ${state.lang==='ms'?'selected':''}>Bahasa Melayu</option></select></label><button class="entry-login" data-action="auth-login">${t('signIn')}${icon('arrow')}</button></nav></header>`}

function illustration(c){const {state,t,local,esc,icon,ranking,skillName}=c;const role=ranking()[0];return `<div class="experience-visual"><div class="visual-orbit orbit-one"></div><div class="visual-orbit orbit-two"></div><span class="visual-plus plus-one">+</span><span class="visual-plus plus-two">+</span><div class="visual-caption">${t('illustrationLabel')}</div><article class="experience-profile"><div class="profile-line"><span class="blue-avatar">${icon('briefcase')}</span><div><span class="visual-eyebrow">${t('experienceValue')}</span><h3>${esc(local(state.profile.role))}</h3><p>${state.profile.years} ${t('years')}</p></div></div><div class="visual-skill-row">${state.profile.skills.slice(0,3).map(s=>`<span>${esc(skillName(s))}</span>`).join('')}</div></article><div class="experience-connector">${icon('arrow')}<span>${t('introTrust1')}</span></div><article class="experience-match"><div class="match-top"><span class="visual-eyebrow">${t('nextDirection')}</span><span class="visual-match-icon">${icon(role.icon)}</span></div><h3>${esc(local(role.title))}</h3><p>${role.matched.length} / ${role.required.length} ${t('retained')}</p><div class="visual-fit-track"><span style="width:${role.score}%"></span></div><div class="visual-gap"><span>${t('needToLearn')}</span><strong>${role.missing.slice(0,2).map(skillName).map(esc).join(' · ')||t('allCovered')}</strong></div></article><span class="visual-bottom-note">EXPERIENCE → POSSIBILITY → PROGRESS</span></div>`}

function workspacePreview(c){const {t,icon,local,ranking,esc}=c;return `<div class="workspace-preview"><div class="preview-window-bar"><span></span><span></span><span></span><small>RePath · ${t('workspace')}</small></div><div class="preview-input"><span class="visual-eyebrow">${t('recipeInput')}</span><strong>${c.state.profile.years} ${t('years')} · ${c.state.profile.hours} ${t('hours')} / ${c.state.lang==='zh'?'周':c.state.lang==='en'?'week':'minggu'}</strong><p>${esc(local(c.state.profile.role))}</p></div><div class="preview-menu-list">${[['compass','overview','outputDesc'],['path','pathway','actionDesc'],['radar','signals','radarSub']].map(([ico,key,desc],i)=>`<article><span class="preview-menu-icon">${icon(ico)}</span><div><h3>${t(key)}</h3><p>${t(desc)}</p></div><span class="preview-order">0${i+1}</span></article>`).join('')}</div><div class="preview-output">${icon('spark')}<div><small>${t('recipeOutput')}</small><strong>${esc(local(ranking()[0].title))} <span>+ 2</span></strong></div></div></div>`}

export function welcomeScreen(c){const {state,t,icon,button,esc}=c;const step=state.welcomeStep;const needKey={transition:'transitionNeed',employed:'employedNeed',returning:'returningNeed'}[state.audience];let content;if(step===0){content=`<div class="intro-copy"><div class="entry-eyebrow"><span></span>${t('introEyebrow')}</div><h1>${t('introTitle')}<br><em>${t('introAccent')}</em></h1><p class="intro-description">${t('introDesc')}</p><div class="intro-audience"><h2>${t('whoQuestion')}</h2><div>${['transition','employed','returning'].map(a=>`<button class="${state.audience===a?'selected':''}" data-action="entry-audience" data-audience="${a}" aria-pressed="${state.audience===a}">${t(a)}</button>`).join('')}</div><p>${icon('check')}${t(needKey)}</p></div><div class="intro-trust">${['introTrust1','introTrust2','introTrust3'].map(k=>`<span>${icon('check')}${t(k)}</span>`).join('')}</div></div>${illustration(c)}`;}else if(step===1){content=`<div class="intro-copy"><div class="entry-eyebrow"><span></span>${t('howEyebrow')}</div><h1>${t('howTitle')}<br><em>${t('howAccent')}</em></h1><p class="intro-description">${t('howDesc')}</p><div class="how-steps">${[['inputTitle','inputDesc'],['outputTitle','outputDesc'],['actionTitle','actionDesc']].map(([title,desc],i)=>`<article><span>0${i+1}</span><div><h2>${t(title)}</h2><p>${t(desc)}</p></div></article>`).join('')}</div></div><div class="intro-preview-wrap"><div class="visual-caption">${t('whereFind')}</div>${workspacePreview(c)}</div>`;}else{const plan=c.getPlan();const first=plan.items[0];content=`<div class="intro-copy"><div class="entry-eyebrow"><span></span>${t('valueEyebrow')}</div><h1>${t('valueTitle')}<br><em>${t('valueAccent')}</em></h1><p class="intro-description">${t('valueDesc')}</p><div class="intro-value-rows"><article><span>FREE</span><div><h2>${t('freeOutcome')}</h2><p>${t('freeOutcomeDesc')}</p></div></article><article class="pro-value-row"><span>PRO</span><div><h2>${t('proOutcome')}</h2><p>${t('proOutcomeDesc')}</p></div></article></div><p class="intro-free-note">${icon('check')}${t('noCard')}</p></div><div class="intro-plan-wrap"><div class="floating-plan-label">${icon('spark')}REPATH PRO</div><div class="intro-plan-card"><div class="plan-card-heading"><span class="visual-eyebrow">${t('weeklyLabel')}</span><span>${plan.items.length} ${t('weeks')}</span></div><h3>${esc(c.local(c.targetRole().title))}</h3><p>${state.profile.hours} ${t('hoursLabel')}</p><article class="intro-week"><span>01</span><div><small>${t('weekLabel').replace('{n}','1')}</small><h4>${t('weekStory')}</h4><p>${t('step1Desc')}</p></div><span class="week-empty-check"></span></article><article class="intro-week muted-week"><span>02</span><div><small>${t('weekLabel').replace('{n}','2')}</small><h4>${t('step2')}</h4></div><span class="week-empty-check"></span></article><div class="intro-plan-summary">${icon('path')}<span>${t('proOutcomeDesc')}</span></div></div><div class="intro-plan-shadow"></div></div>`;}
return `<main class="entry-main"><section class="intro-stage view-enter" aria-label="${t('introStepNames')[step]}">${content}</section><footer class="entry-step-footer"><div class="step-controls">${step>0?button(t('previous'),'intro-back','intro-back','arrow'):`<button class="intro-back" data-action="auth-login">${t('skipIntro')}</button>`}</div><div class="intro-pagination">${t('introStepNames').map((label,i)=>`<button data-action="intro-goto" data-step="${i}" class="${step===i?'active':''}" aria-label="${esc(label)}" ${step===i?'aria-current="step"':''}><span>0${i+1}</span>${esc(label)}</button>`).join('')}</div>${button(t(step===2?'startNow':'nextIntro'),step===2?'auth-start':'intro-next','primary-button entry-next','arrow')}</footer></main>`}

export function authScreen(c){const {state,t,brandMark,button,icon,esc}=c;const register=state.authMode==='signup';return `<main class="account-layout view-enter"><section class="account-story"><div class="entry-eyebrow"><span></span>${t('accountEyebrow')}</div><h1>${t('accountTitle')}</h1><p>${t('accountDesc')}</p><div class="account-story-list">${[['compass','setupResult1'],['layers','setupResult2'],['path','setupResult3']].map(([ico,key])=>`<div>${icon(ico)}<span>${t(key)}</span></div>`).join('')}</div><div class="account-art">${brandMark()}<span class="account-art-line"></span><span>${icon('compass')}</span><span class="account-art-line"></span><span>${icon('path')}</span></div><span class="account-small">${t('noCard')}</span></section><section class="account-card"><div class="account-tabs"><button data-action="auth-mode" data-mode="signin" class="${register?'':'active'}">${t('signIn')}</button><button data-action="auth-mode" data-mode="signup" class="${register?'active':''}">${t('signUp')}</button></div><h2>${t(register?'signUp':'signIn')} RePath</h2><p>${t('firstStepTime')}</p><form id="account-form"><label class="field">${t('nickname')}<input name="nickname" maxlength="40" value="${register?'':esc(state.profile.name)}" placeholder="${t('nicknameHint')}" autocomplete="off" required></label><div class="account-demo-notice">${icon('info')}<p>${t('accountHint')}</p></div><button type="submit" class="primary-button">${t(register?'registerContinue':'loginContinue')}${icon('arrow')}</button></form><div class="account-divider"><span>${t('guestNote')}</span></div>${button(t('guestContinue'),'guest-example','small-button','arrow')}<button class="back-intro-link" data-action="intro-home">${t('backToIntro')}</button></section></main>`}

export function setupScreen(c){const {state,t,local,esc,icon,button,skillName}=c;const step=state.setupStep;let fields;if(step===0){fields=`<div class="setup-audience-grid">${['transition','employed','returning'].map(a=>`<button type="button" class="${state.audience===a?'active':''}" data-action="entry-audience" data-audience="${a}">${icon({transition:'compass',employed:'chart',returning:'path'}[a])}<strong>${t(a)}</strong>${state.audience===a?icon('check'):''}</button>`).join('')}</div><div class="setup-fields-grid"><label class="field">${t('previousRole')}<input name="role" value="${esc(c.profileRole())}" maxlength="100" required></label><label class="field">${t('experience')}<input type="number" name="years" min="0" max="45" value="${state.profile.years}" required></label></div>`;}else if(step===1){fields=`<div class="setup-skills-grid">${Object.keys(skills).map(s=>`<label class="setup-skill"><input type="checkbox" name="skills" value="${s}" ${state.profile.skills.includes(s)?'checked':''}><span>${icon('check')}</span><strong>${esc(skillName(s))}</strong><small>SDG 4</small></label>`).join('')}</div><div class="setup-skill-count"><span id="skill-count">${state.profile.skills.length}</span> ${t('setupSelected')}</div>`;}else{fields=`<div class="setup-hours"><label for="setup-hours">${t('hoursLabel')}</label><strong><output id="hours-display">${state.profile.hours}</output><small>${t('hours')}</small></strong><input id="setup-hours" name="hours" type="range" min="1" max="20" value="${Math.min(20,state.profile.hours)}"><div><span>1 ${t('hours')}</span><span>20 ${t('hours')}</span></div></div><label class="field setup-budget">${t('budget')}<select name="budget"><option value="free" ${state.profile.budget==='free'?'selected':''}>${t('freeOnly')}</option><option value="low" ${state.profile.budget==='low'?'selected':''}>${t('lowCost')}</option></select></label>`;}
return `<main class="setup-layout view-enter"><aside class="setup-progress"><div class="entry-eyebrow">${t('setupEyebrow')}</div><h2>${t('buildProfile')}</h2><ol>${[0,1,2].map(i=>`<li class="${step===i?'active':step>i?'done':''}"><span>${step>i?icon('check'):'0'+(i+1)}</span><div>${t('setupStep'+i)}</div></li>`).join('')}</ol><div class="setup-progress-note">${icon('lock')}<p>${t('synthetic')}<br>${t('changeLater')}</p></div></aside><section class="setup-content"><div class="setup-count">0${step+1} / 03</div><h1>${t('setupTitle'+step)}</h1><p>${t('setupDesc'+step)}</p><form id="setup-form">${fields}<div class="setup-form-actions">${button(t('previous'),'setup-back','small-button',null,'type="button"')}<button type="submit" class="primary-button">${t(step===2?'generatePaths':'continueSetup')}${icon('arrow')}</button></div></form><div class="setup-preview-outcome"><h3>${t('setupWhatNext')}</h3>${['setupResult1','setupResult2','setupResult3'].map(k=>`<span>${icon('check')}${t(k)}</span>`).join('')}</div></section></main>`}

export function onboardingGuide(c){const {t,button,ranking}=c;return `<section class="workspace-guide"><div class="guide-steps">${[['check','guideStep1'],['compass','guideStep2'],['path','guideStep3']].map(([ico,key],i)=>`<div class="${i===0?'done':''}"><span>${c.icon(ico)}</span><strong>${t(key)}</strong></div>`).join('')}</div>${button(t('guideCTA'),'choose','small-button','arrow',`data-id="${ranking()[0].id}"`)}</section>`}

function weekCopy(c,item){if(item.stage==='applications')return {title:c.t('weekApplications'),description:c.t('weekApplicationsDesc')};if(item.stage==='story'&&c.state.profile.project?.name)return {title:c.t('weekStory'),description:c.state.profile.project.name+' — '+(c.state.profile.project.result||c.t('step1Desc'))};if(item.stage==='learn'&&item.skillId){const phase=item.phase||'apply';return {title:c.t('weekLearn').replace('{skill}',c.skillName(item.skillId))+' · '+c.t('phase_'+phase),description:phase==='apply'?c.local(learningExercises[item.skillId]):c.t('phase_'+phase+'_desc').replace('{skill}',c.skillName(item.skillId))};}const labels={story:['weekStory','step1Desc'],project:['weekProject','step3Desc'],review:['weekReview','weekReviewDesc'],sprint:['weekSprint','weekGeneric'],learn:['step2','weekGeneric']};const [title,description]=labels[item.stage]||labels.learn;return {title:c.t(title),description:c.t(description)}}

export function executionPanel(c){const {state,t,icon,button,esc}=c;const plan=c.getPlan();const completed=state.weeklyProgress[plan.roleId]||[];const visible=state.pro?plan.items:plan.items.slice(0,1);const role=c.targetRole();return `<section class="execution-panel ${state.pro?'unlocked':'locked'}" id="execution"><div class="execution-heading"><div><div class="mini-eyebrow">${t('weeklyLabel')}</div><h2>${t(state.pro?'executionTitle':'executionPreview')}</h2><p>${t('executionDesc')}</p></div><span class="pro-feature-badge">${icon('spark')}PRO</span></div><div class="execution-metrics"><div><strong>${plan.items.length}<small>${t('weeks')}</small></strong><span>${t('estimated')}</span></div><div><strong>${plan.totalHours}<small>${t('hours')}</small></strong><span>${t('plannedHours')}</span></div><div><strong>${completed.length}<small>/ ${plan.items.length}</small></strong><span>${t('planProgress')}</span></div></div><div class="weekly-list">${visible.map(item=>{const copy=weekCopy(c,item);const done=completed.includes(item.id);return `<article class="weekly-task ${done?'done':''}"><div class="weekly-index">${String(item.week).padStart(2,'0')}</div><div class="weekly-body"><div class="weekly-task-heading"><span>${t('weekLabel').replace('{n}',item.week)}</span><span>~ ${item.hours} ${t('hours')}</span></div><h3>${esc(copy.title)}</h3><p>${esc(copy.description)}</p>${item.resource?`<a class="source-link" href="${item.resource.url}" target="_blank" rel="noopener noreferrer">${esc(item.resource.provider)} ${icon('external')}</a>`:`<small>${t('practice')} · SDG ${item.stage==='learn'?4:role.sdg}</small>`}</div>${state.pro?`<button class="weekly-check ${done?'checked':''}" data-action="weekly-complete" data-week="${item.id}" aria-label="${t(done?'weeklyUndo':'weeklyDone')} · ${t('weekLabel').replace('{n}',item.week)}" aria-pressed="${done}">${icon('check')}</button>`:`<span class="weekly-preview-label">${t('demo')}</span>`}</article>`}).join('')}</div>${!state.pro?`<div class="weekly-locked"><span class="weekly-lock-icon">${icon('lock')}</span><div><strong>${t('remainingWeeks').replace('{n}',Math.max(0,plan.items.length-1))}</strong><p>${t('proOnlyHint')}</p></div>${button(t('unlockExecution'),'enable-pro','primary-button','arrow')}</div>`:`<div class="weekly-plan-note">${icon('info')}${t('learningEstimate')}</div>`}</section>`}

export function reflectionPanel(c){if(!c.state.pro)return '';const {state,t,icon,button,esc}=c;const role=c.targetRole();const records=state.reflections.filter(r=>r.roleId===role.id);return `<section class="reflection-panel"><div class="mini-eyebrow">LEARN. REFLECT. REPATH.</div><h2>${t('selfReflection')}</h2><p>${t('reflectionDesc')}</p><div class="reflection-skills">${role.missing.length?role.missing.map(s=>`<article><div>${icon('layers')}<strong>${esc(c.skillName(s))}</strong></div>${button(t('confirmSkill'),'reflect-skill','small-button','arrow',`data-id="${s}"`)}</article>`).join(''):`<p>${t('allSkillsBuilt')}</p>`}</div>${records.length?`<div class="growth-history"><h3>${t('growthHistory')}</h3>${records.map(r=>`<article><span>${icon('check')}${esc(c.skillName(r.skillId))}<small>${t('selfReported')} · ${esc(new Date(r.timestamp).toLocaleDateString(state.lang==='zh'?'zh-CN':state.lang==='en'?'en-GB':'ms-MY'))}</small></span><strong>${r.before}<span>→</span>${r.after}<small>/100</small></strong></article>`).join('')}</div>`:''}<p class="reflection-note">${icon('info')}${t('selfReportNote')}</p></section>`}

export function pricingStory(c){const {t,icon}=c;return `<section class="pricing-story"><article><span class="pricing-story-tag">FREE · ${t('planBenefit1')}</span><h2>“${t('freeExample')}”</h2><p>${t('freeOutcomeDesc')}</p></article><div>${icon('arrow')}</div><article><span class="pricing-story-tag">PRO · ${t('planBenefit2')}</span><h2>“${t('proExample')}”</h2><p>${t('proOutcomeDesc')}</p></article></section>`}

export function upgradePreview(c){const {t,button}=c;return `<section class="path-upgrade"><div><span class="pro-pill">REPATH PRO</span><h3>${t('starterNext')}</h3><p>${t('proOutcomeDesc')}</p></div>${button(t(c.state.pro?'viewFullPlan':'proPreviewButton'),'scroll-execution','primary-button','arrow')}</section>`}
